@startuml

class WebPortal {
  + VersionNumber : string
  + URLAddress : string
}

class Building {
  + ID : string
  + Name : string
  + EnergyClass : string
  + Address : string
  + YearOfConstruction : int
}

class AdditionalEntry {
  + Name : string
  + IsPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + Value : float
  + Unit : string
}

class Image {
  + FileName : string
  + IsProfilePhoto : boolean
}

class User {
  + UserName : string
  + Email : string
  + Password : string
  + IsActivated : boolean
}

class Administrator extends User {
  + IDCardNumber : string
}

class Comment {
  + Text : string
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
WebPortal "1" -- "*" Visitor
Building "1" -- "*" AdditionalEntry
Building "1" -- "*" Image
Building "1" -- "*" Comment
User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
Visitor "1" -- "*" Building : searches

@enduml

